def shifted_logits(logits, residual, base_actions):
    import jax.numpy as jnp
    return tuple((head + residual[..., i, None] * (jnp.arange(dim, dtype=jnp.float32) - base_actions[..., i, None]) for (i, (head, dim)) in enumerate(zip(logits, SPEC['action_dims'], strict=True))))

def make_tokens(observations, base_actions):
    obs = np.asarray(observations, np.float32)
    actions = np.asarray(base_actions, np.float32)
    if obs.ndim != 2 or obs.shape[1] != 21 or actions.shape != (len(obs), 5):
        raise ValueError('21 observation and5 native action coordinates required')
    if not np.isfinite(obs).all() or not np.isfinite(actions).all():
        raise ValueError('nonfinite token')
    return np.concatenate((np.clip(obs, -10.0, 10.0), actions / np.asarray([30.0, 80.0, 40.0, 40.0, 4.0], np.float32)), axis=-1)

