def means(logits):
    import jax.numpy as jnp
    result = []
    for head in logits:
        left = jnp.minimum(jnp.argmax(head, axis=-1), head.shape[-1] - 2)
        a = jnp.take_along_axis(head, left[..., None], axis=-1)[..., 0]
        b = jnp.take_along_axis(head, (left + 1)[..., None], axis=-1)[..., 0]
        result.append(left.astype(jnp.float32) + 0.5 + b - a)
    return jnp.stack(result, axis=-1)

