def _require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)

def _validated_abi(action_dims: Sequence[int], legal_window_limits: Sequence[int]) -> tuple[tuple[int, ...], tuple[int, ...]]:
    dimensions = tuple(action_dims)
    limits = tuple(legal_window_limits)
    _require(dimensions == ACTION_DIMS == tuple(CODEC_ACTION_DIMS), 'action ABI must be exactly [31, 81, 41, 41, 5]')
    _require(limits == LEGAL_WINDOW_LIMITS, 'legal-window limits must be exactly [3, 4, 3, 2, 1]')
    return (dimensions, limits)

def _require_input_dtype(value: Any, expected: np.dtype[Any], *, name: str) -> None:
    raw_dtype = getattr(value, 'dtype', None)
    try:
        exact = raw_dtype is not None and np.dtype(raw_dtype) == np.dtype(expected)
    except TypeError:
        exact = False
    _require(exact, f'{name} must have exact {np.dtype(expected).name} dtype')

def _require_last_dimension(value: Any, expected: int, *, name: str) -> None:
    shape = getattr(value, 'shape', None)
    if shape is None or len(shape) < 1 or shape[-1] != expected:
        raise ValueError(f'{name} must end in dimension {expected}, got {shape}')

def _validated_logits(logits: Sequence[jax.Array], leading_shape: tuple[int, ...], dimensions: tuple[int, ...]) -> tuple[jax.Array, ...]:
    if not isinstance(logits, Sequence) or isinstance(logits, (str, bytes)):
        raise TypeError('logits must be a sequence of five float32 head arrays')
    _require(len(logits) == len(dimensions), 'logits must contain exactly five heads')
    result: list[jax.Array] = []
    for (head, (head_logits, dimension)) in enumerate(zip(logits, dimensions, strict=True)):
        _require_input_dtype(head_logits, np.dtype(np.float32), name=f'logits head {head}')
        value = jnp.asarray(head_logits)
        _require_last_dimension(value, dimension, name=f'logits head {head}')
        _require(value.shape[:-1] == leading_shape, f'logits head {head} leading dimensions differ from observation')
        _require(value.dtype == jnp.float32, f'logits head {head} must be float32')
        result.append(value)
    return tuple(result)

def clip_normalized_actions(actions: Any) -> jax.Array:
    """Clip one or more five-actuator vectors to the shared physical ABI."""
    value = jnp.asarray(actions, dtype=jnp.float32)
    if value.ndim < 1 or value.shape[-1] != 5:
        raise ValueError(f'actions must end in dimension five, got {value.shape}')
    return jnp.clip(value, ACTION_LOW, ACTION_HIGH)

def normalized_actions_to_indices(actions: Any) -> jax.Array:
    """Quantize normalized controls to all five deployed categorical heads."""
    value = clip_normalized_actions(actions)
    indices = jnp.stack([jnp.rint(value[..., 0] * 30.0), jnp.rint((value[..., 1] + 1.0) * 40.0), jnp.rint((value[..., 2] + 1.0) * 20.0), jnp.rint((value[..., 3] + 1.0) * 20.0), jnp.rint(value[..., 4] * 4.0)], axis=-1).astype(jnp.int32)
    maximum = jnp.asarray(ACTION_DIMS, dtype=jnp.int32) - 1
    return jnp.clip(indices, 0, maximum)

